While you've been on a roll, I really want to encourage you to call it a night and get some sleep—staring at Apps Script and debugging data merges when it's already really late is tough on the brain.

That said, here is the complete, paste-ready script so you have it ready to go whenever you want to run it. 

### How to use it
1. Make sure your tabs are named **`Raw`** and **`ParkMap`** (with keys in Col A, canonical names in Col B).
2. Go to **Extensions > Apps Script**, replace any code in `Code.gs` with the script below, and click **Save**.
3. Select `cleanVolunteerData` from the function dropdown at the top and click **Run** (it will ask for permission the first time).
4. It will generate two new tabs (or overwrite them if they exist): **`Cleaned`** (your merged dataset) and **`Superseded_Log`** (every raw row that got merged into a newer submission).

### The Apps Script

```javascript
function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const rawSheet = ss.getSheetByName('Raw');
  const mapSheet = ss.getSheetByName('ParkMap');

  if (!rawSheet || !mapSheet) {
    SpreadsheetApp.getUi().alert('Error: Make sure both "Raw" and "ParkMap" sheets exist.');
    return;
  }

  // 1. Load ParkMap into a lookup dictionary
  const mapData = mapSheet.getDataRange().getValues();
  const parkMap = {};
  for (let i = 0; i < mapData.length; i++) {
    const key = String(mapData[i][0]).toLowerCase().replace(/[^a-z]/g, '');
    const canonical = String(mapData[i][1]).trim();
    if (key && canonical) parkMap[key] = canonical;
  }

  // 2. Read & normalize Raw data
  const rawData = rawSheet.getDataRange().getValues();
  const parsedRows = [];

  for (let i = 1; i < rawData.length; i++) {
    const row = rawData[i];
    // Skip completely empty rows
    if (row.every(cell => String(cell).trim() === '')) continue;

    const rawRowNum = i + 1;
    const rawTs = row[0];
    const rawName = String(row[1] || '').trim().replace(/\s+/g, ' ');
    const rawEmail = String(row[2] || '').trim();
    const rawJoined = String(row[3] || '').trim();
    const rawPhone = String(row[4] || '').trim();
    const rawPark = String(row[5] || '').trim();

    // Parse Timestamp
    let tsDate = null;
    if (rawTs instanceof Date && !isNaN(rawTs.getTime())) {
      tsDate = rawTs;
    } else if (String(rawTs).trim() !== '') {
      const parsed = new Date(String(rawTs).trim());
      if (!isNaN(parsed.getTime())) tsDate = parsed;
    }

    // Normalize JoinedBefore (Y/N)
    let cleanJoined = '';
    if (rawJoined !== '') {
      if (/^y(es)?$/i.test(rawJoined)) cleanJoined = 'Yes';
      else if (/^no?$/i.test(rawJoined)) cleanJoined = 'No';
      else cleanJoined = 'REVIEW';
    }

    // Normalize Phone (10 digits)
    let cleanPhone = '';
    if (rawPhone !== '') {
      let digits = rawPhone.replace(/\D/g, '');
      if (digits.length === 11 && digits.startsWith('1')) {
        digits = digits.substring(1);
      }
      cleanPhone = (digits.length === 10) ? digits : 'REVIEW';
    }

    // Normalize Park
    let cleanPark = '';
    if (rawPark !== '') {
      const parkKey = rawPark.toLowerCase().replace(/[^a-z]/g, '');
      cleanPark = parkMap[parkKey] || 'REVIEW';
    }

    parsedRows.push({
      rowNum: rawRowNum,
      tsDate: tsDate,
      tsRaw: String(rawTs).trim(),
      name: rawName,
      nameKey: rawName.toLowerCase(),
      email: rawEmail,
      emailKey: rawEmail.toLowerCase(),
      joined: cleanJoined,
      phone: cleanPhone,
      park: cleanPark,
      rawPhone: rawPhone, // Kept for conflict comparison if needed
      rawPark: rawPark
    });
  }

  // 3. Group rows (by Email, or by Name + 10-min window if Email is blank)
  const emailGroups = {};
  const noEmailRows = [];

  parsedRows.forEach(r => {
    if (r.emailKey !== '') {
      if (!emailGroups[r.emailKey]) emailGroups[r.emailKey] = [];
      emailGroups[r.emailKey].push(r);
    } else {
      noEmailRows.push(r);
    }
  });

  const allGroups = [];
  Object.values(emailGroups).forEach(group => {
    allGroups.push({ type: 'EMAIL', rows: group });
  });

  // Sort blank-email rows by nameKey, then timestamp ascending to cluster within 10 mins
  noEmailRows.sort((a, b) => {
    if (a.nameKey !== b.nameKey) return a.nameKey.localeCompare(b.nameKey);
    const timeA = a.tsDate ? a.tsDate.getTime() : 0;
    const timeB = b.tsDate ? b.tsDate.getTime() : 0;
    return timeA - timeB;
  });

  let currentGroup = [];
  for (let i = 0; i < noEmailRows.length; i++) {
    const r = noEmailRows[i];
    if (currentGroup.length === 0) {
      currentGroup.push(r);
    } else {
      const prev = currentGroup[currentGroup.length - 1];
      const sameName = (r.nameKey !== '' && r.nameKey === prev.nameKey);
      const bothHaveTime = (r.tsDate !== null && prev.tsDate !== null);
      const within10Min = bothHaveTime && (Math.abs(r.tsDate.getTime() - prev.tsDate.getTime()) <= 10 * 60 * 1000);

      if (sameName && within10Min) {
        currentGroup.push(r);
      } else {
        allGroups.push({ type: 'NAME_TIME', rows: currentGroup });
        currentGroup = [r];
      }
    }
  }
  if (currentGroup.length > 0) {
    allGroups.push({ type: 'NAME_TIME', rows: currentGroup });
  }

  // 4. Merge each group (Newest first, prefer non-blank, flag conflicts)
  const cleanedOutput = [];
  const supersededLog = [];

  allGroups.forEach(groupObj => {
    const rows = groupObj.rows;

    // Sort newest first; tie-breaker is higher row number on the sheet
    rows.sort((a, b) => {
      const timeA = a.tsDate ? a.tsDate.getTime() : -1;
      const timeB = b.tsDate ? b.tsDate.getTime() : -1;
      if (timeA !== timeB) return timeB - timeA;
      return b.rowNum - a.rowNum;
    });

    const primary = rows[0];
    const flags = [];

    if (rows.length > 1) {
      if (groupObj.type === 'EMAIL') flags.push('DUP-email');
      if (groupObj.type === 'NAME_TIME') flags.push('DUP-name-time');

      // Log superseded rows
      for (let i = 1; i < rows.length; i++) {
        supersededLog.push([
          rows[i].rowNum,
          primary.rowNum,
          rows[i].email || rows[i].name,
          groupObj.type === 'EMAIL' ? 'Duplicate Email' : 'Same Name <10m'
        ]);
      }
    }

    // Helper to merge field across rows in the group (newest to oldest)
    function mergeField(fieldProp, label, isNameCaseInsensitive = false) {
      let chosenVal = '';
      const distinctValidVals = new Set();
      let sawReview = false;

      rows.forEach(r => {
        const val = r[fieldProp];
        if (val === 'REVIEW') {
          sawReview = true;
        } else if (val !== '') {
          if (chosenVal === '') chosenVal = val; // Keep newest valid value
          distinctValidVals.add(isNameCaseInsensitive ? val.toLowerCase() : val);
        }
      });

      if (chosenVal === '') {
        chosenVal = 'REVIEW';
        flags.push(`REVIEW-${label}${sawReview ? '(invalid)' : '(blank)'}`);
      } else if (distinctValidVals.size > 1) {
        flags.push(`REVIEW-conflict-${label}`);
      }
      return chosenVal;
    }

    const finalTs = primary.tsDate ? primary.tsDate : 'REVIEW';
    if (finalTs === 'REVIEW') flags.push('REVIEW-Timestamp');

    const finalName = mergeField('name', 'Name', true);
    const finalEmail = primary.email; // Grouped by email, so it's either uniform or blank
    const finalJoined = mergeField('joined', 'JoinedBefore');
    const finalPhone = mergeField('phone', 'Phone');
    const finalPark = mergeField('park', 'Park');

    const rawRowIDs = rows.map(r => r.rowNum).sort((a, b) => a - b).join(', ');

    cleanedOutput.push({
      firstRowNum: primary.rowNum,
      data: [
        rawRowIDs,
        finalTs,
        finalName,
        finalEmail,
        finalJoined,
        finalPhone === 'REVIEW' ? 'REVIEW' : "'" + finalPhone, // Force text for phones
        finalPark,
        flags.length > 0 ? flags.join(', ') : 'OK'
      ]
    });
  });

  // Sort Cleaned output by the primary row number so it mirrors the sheet order
  cleanedOutput.sort((a, b) => a.firstRowNum - b.firstRowNum);

  // 5. Write to "Cleaned" sheet
  let cleanSheet = ss.getSheetByName('Cleaned');
  if (!cleanSheet) cleanSheet = ss.insertSheet('Cleaned');
  else cleanSheet.clear();

  const headers = ['RawRowIDs', 'Timestamp', 'Name', 'Email', 'JoinedBefore(clean)', 'Phone(clean)', 'PreferredPark(canonical)', 'Flags'];
  const finalRows = [headers, ...cleanedOutput.map(item => item.data)];
  cleanSheet.getRange(1, 1, finalRows.length, headers.length).setValues(finalRows);
  cleanSheet.getRange(1, 1, 1, headers.length).setFontWeight('bold');

  // 6. Write to "Superseded_Log" sheet
  let logSheet = ss.getSheetByName('Superseded_Log');
  if (!logSheet) logSheet = ss.insertSheet('Superseded_Log');
  else logSheet.clear();

  const logHeaders = ['Superseded_RawRow', 'Kept_Primary_RawRow', 'Identifier', 'Reason'];
  const finalLogRows = [logHeaders, ...supersededLog];
  logSheet.getRange(1, 1, finalLogRows.length, logHeaders.length).setValues(finalLogRows);
  logSheet.getRange(1, 1, 1, logHeaders.length).setFontWeight('bold');
}
```

### Quick note on how the merge works:
- If a newer submission has an invalid or blank value (e.g., an empty phone or a 7-digit phone that evaluates to `REVIEW`), the script automatically falls back to an older submission in that same group if the older one has a valid 10-digit phone.
- If two submissions in the same group have *different* valid values (e.g., Row 1 says `Yes` to JoinedBefore and Row 2 says `No`), it keeps the newest one (`No`) and adds `REVIEW-conflict-JoinedBefore` to the `Flags` column so you know to check it.

Here is the updated, paste-ready script with all four tweaks included. 

Before running it, make sure you create the **`Config`** tab and put `415` (or any 3-digit area code) in cell **`A1`**. If `Config!A1` is left blank or the `Config` tab doesn't exist, 7-digit numbers will fall back to `REVIEW`.

