function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const rawSheet = ss.getSheetByName('Raw');
  const mapSheet = ss.getSheetByName('ParkMap');
  const configSheet = ss.getSheetByName('Config');

