    const canonical = String(mapData[i][1]).trim();
    if (key && canonical) parkMap[key] = canonical;
  }

  // 2. Read & normalize Raw data
  const rawData = rawSheet.getDataRange().getValues();
  const rawDisplayData = rawSheet.getDataRange().getDisplayValues(); // Preserves exact raw text
  const parsedRows = [];

  for (let i = 1; i < rawData.length; i++) {
    const row = rawData[i];
    const dispRow = rawDisplayData[i];
    // Skip completely empty rows
    if (row.every(cell => String(cell).trim() === '')) continue;

    const rawRowNum = i + 1;
    const rawTs = row[0];
    const rawTsStr = dispRow[0].trim();
    const rawName = String(row[1] || '').trim().replace(/\s+/g, ' ');
    const rawEmail = String(row[2] || '').trim();
    const rawJoined = String(row[3] || '').trim();
    const rawPhoneStr = dispRow[4].trim();
    const rawPark = String(row[5] || '').trim();

    // Parse Timestamp
    let tsDate = null;
    if (rawTs instanceof Date && !isNaN(rawTs.getTime())) {
      tsDate = rawTs;
    } else if (rawTsStr !== '') {
      const parsed = new Date(rawTsStr);
      if (!isNaN(parsed.getTime())) tsDate = parsed;
    }

    // Normalize JoinedBefore (Y/N)
    let cleanJoined = '';
    if (rawJoined !== '') {
      if (/^y(es)?$/i.test(rawJoined)) cleanJoined = 'Yes';
      else if (/^no?$/i.test(rawJoined)) cleanJoined = 'No';
      else cleanJoined = 'REVIEW';
    }

    // Normalize Phone (10 digits, or 7 digits + defaultAreaCode)
    let cleanPhone = '';
    let filledAreaCode = false;
    if (rawPhoneStr !== '') {
      let digits = rawPhoneStr.replace(/\D/g, '');
      if (digits.length === 11 && digits.startsWith('1')) {
        digits = digits.substring(1);
      }
      if (digits.length === 10) {
        cleanPhone = digits;
      } else if (digits.length === 7 && defaultAreaCode !== '') {
        cleanPhone = defaultAreaCode + digits;
        filledAreaCode = true;
      } else {
        cleanPhone = 'REVIEW';
      }
    }

    // Normalize Park
    let cleanPark = '';
    if (rawPark !== '') {
      const parkKey = rawPark.toLowerCase().replace(/[^a-z]/g, '');
      cleanPark = parkMap[parkKey] || 'REVIEW';
    }

    parsedRows.push({
      rowNum: rawRowNum,
      tsDate: tsDate,
      tsRaw: rawTsStr,
      name: rawName,
      nameKey: rawName.toLowerCase(),
      email: rawEmail,
      emailKey: rawEmail.toLowerCase(),
      joined: cleanJoined,
      phone: cleanPhone,
      phoneFilled: filledAreaCode,
      rawPhone: rawPhoneStr,
      park: cleanPark
    });
  }

  // 3. Group rows (by Email, or by Name + 10-min window if Email is blank)
  const emailGroups = {};
  const noEmailRows = [];

  parsedRows.forEach(r => {
    if (r.emailKey !== '') {
      if (!emailGroups[r.emailKey]) emailGroups[r.emailKey] = [];
      emailGroups[r.emailKey].push(r);
    } else {
      noEmailRows.push(r);
    }
  });

  const allGroups = [];
  Object.values(emailGroups).forEach(group => {
    allGroups.push({ type: 'EMAIL', rows: group });
  });

  // Sort blank-email rows by nameKey, then timestamp ascending to cluster within 10 mins
  noEmailRows.sort((a, b) => {
    if (a.nameKey !== b.nameKey) return a.nameKey.localeCompare(b.nameKey);
    const timeA = a.tsDate ? a.tsDate.getTime() : 0;
    const timeB = b.tsDate ? b.tsDate.getTime() : 0;
    return timeA - timeB;
  });

  let currentGroup = [];
  for (let i = 0; i < noEmailRows.length; i++) {
    const r = noEmailRows[i];
    if (currentGroup.length === 0) {
      currentGroup.push(r);
    } else {
      const prev = currentGroup[currentGroup.length - 1];
      const sameName = (r.nameKey !== '' && r.nameKey === prev.nameKey);
      const bothHaveTime = (r.tsDate !== null && prev.tsDate !== null);
      const within10Min = bothHaveTime && (Math.abs(r.tsDate.getTime() - prev.tsDate.getTime()) <= 10 * 60 * 1000);

      if (sameName && within10Min) {
        currentGroup.push(r);
      } else {
        allGroups.push({ type: 'NAME_TIME', rows: currentGroup });
        currentGroup = [r];
      }
    }
  }
  if (currentGroup.length > 0) {
    allGroups.push({ type: 'NAME_TIME', rows: currentGroup });
  }

  // 4. Merge each group (Newest first, prefer non-blank, flag conflicts)
  const cleanedOutput = [];
  const supersededLog = [];
  const flagCounts = {};

  function recordFlag(list, flagStr) {
    list.push(flagStr);
    flagCounts[flagStr] = (flagCounts[flagStr] || 0) + 1;
  }

  allGroups.forEach(groupObj => {
    const rows = groupObj.rows;

    // Sort newest first; tie-breaker is higher row number on the sheet
    rows.sort((a, b) => {
      const timeA = a.tsDate ? a.tsDate.getTime() : -1;
      const timeB = b.tsDate ? b.tsDate.getTime() : -1;
      if (timeA !== timeB) return timeB - timeA;
      return b.rowNum - a.rowNum;
    });

    const primary = rows[0];
    const flags = [];

    if (rows.length > 1) {
      if (groupObj.type === 'EMAIL') recordFlag(flags, 'DUP-email');
      if (groupObj.type === 'NAME_TIME') recordFlag(flags, 'DUP-name-time');

      for (let i = 1; i < rows.length; i++) {
        supersededLog.push([
          rows[i].rowNum,
          primary.rowNum,
          rows[i].email || rows[i].name,
          groupObj.type === 'EMAIL' ? 'Duplicate Email' : 'Same Name <10m'
        ]);
      }
    }

    // Helper to merge field across rows in the group (newest to oldest)
    function mergeField(fieldProp, label, isNameCaseInsensitive = false) {
      let chosenVal = '';
      let chosenRow = null;
      const distinctValidVals = new Set();
      let sawReview = false;

      rows.forEach(r => {
        const val = r[fieldProp];
        if (val === 'REVIEW') {
          sawReview = true;
        } else if (val !== '') {
          if (chosenVal === '') {
            chosenVal = val;
            chosenRow = r;
          }
          distinctValidVals.add(isNameCaseInsensitive ? val.toLowerCase() : val);
        }
      });

      if (chosenVal === '') {
        chosenVal = 'REVIEW';
        recordFlag(flags, `REVIEW-${label}${sawReview ? '(invalid)' : '(blank)'}`);
      } else if (distinctValidVals.size > 1) {
        recordFlag(flags, `REVIEW-conflict-${label}`);
      }
      return { val: chosenVal, sourceRow: chosenRow };
    }

    // Timestamp handling (Keep raw string if unparsed, but flag REVIEW-Timestamp)
    let finalTs = primary.tsDate;
    const rawTsOut = primary.tsRaw;
    if (!finalTs) {
      finalTs = rawTsOut;
      recordFlag(flags, 'REVIEW-Timestamp');
    }

    const finalName = mergeField('name', 'Name', true).val;
    const finalEmail = primary.email;
    const finalJoined = mergeField('joined', 'JoinedBefore').val;

    const phoneMerge = mergeField('phone', 'Phone');
    const finalPhone = phoneMerge.val;
    if (phoneMerge.sourceRow && phoneMerge.sourceRow.phoneFilled) {
      recordFlag(flags, 'FILLED-areaCode');
    }
    const rawPhoneOut = phoneMerge.sourceRow ? phoneMerge.sourceRow.rawPhone : primary.rawPhone;

    const finalPark = mergeField('park', 'Park').val;
    const rawRowIDs = rows.map(r => r.rowNum).sort((a, b) => a - b).join(', ');

    cleanedOutput.push({
      firstRowNum: primary.rowNum,
      data: [
        rawRowIDs,
         "'" + rawTsOut, // Force text so raw string isn't auto-converted
        finalTs,
        finalName,
        finalEmail,
        finalJoined,
        "'" + rawPhoneOut,
        finalPhone === 'REVIEW' ? 'REVIEW' : "'" + finalPhone,
        finalPark,
        flags.length > 0 ? flags.join(', ') : 'OK'
      ]
    });
  });

  // Sort Cleaned output by the primary row number
  cleanedOutput.sort((a, b) => a.firstRowNum - b.firstRowNum);

  // 5. Write to "Cleaned" sheet
  let cleanSheet = ss.getSheetByName('Cleaned');
  if (!cleanSheet) cleanSheet = ss.insertSheet('Cleaned');
  else cleanSheet.clear();

  const headers = [
    'RawRowIDs', 'RawTimestamp', 'Timestamp', 'Name', 'Email', 
    'JoinedBefore(clean)', 'RawPhone', 'Phone(clean)', 'PreferredPark(canonical)', 'Flags'
  ];
  const finalRows = [headers, ...cleanedOutput.map(item => item.data)];
  cleanSheet.getRange(1, 1, finalRows.length, headers.length).setValues(finalRows);
  cleanSheet.getRange(1, 1, 1, headers.length).setFontWeight('bold');

  // 6. Write to "Superseded_Log" sheet
  let logSheet = ss.getSheetByName('Superseded_Log');
  if (!logSheet) logSheet = ss.insertSheet('Superseded_Log');
  else logSheet.clear();

  const logHeaders = ['Superseded_RawRow', 'Kept_Primary_RawRow', 'Identifier', 'Reason'];
  const finalLogRows = [logHeaders, ...supersededLog];
  logSheet.getRange(1, 1, finalLogRows.length, logHeaders.length).setValues(finalLogRows);
  logSheet.getRange(1, 1, 1, logHeaders.length).setFontWeight('bold');

  // 7. Write to "Summary" sheet
  let sumSheet = ss.getSheetByName('Summary');
  if (!sumSheet) sumSheet = ss.insertSheet('Summary');
  else sumSheet.clear();

  const summaryRows = [
    ['Metric', 'Count'],
    ['Total Raw Rows', parsedRows.length],
    ['Total Groups', allGroups.length],
    ['Cleaned Rows Written', cleanedOutput.length],
    ['Superseded Rows', supersededLog.length],
    ['', ''],
    ['Flag Breakdown (Review & Info)', 'Count']
  ];

  const sortedFlags = Object.keys(flagCounts).sort();
  if (sortedFlags.length === 0) {
    summaryRows.push(['None', 0]);
  } else {
    sortedFlags.forEach(f => summaryRows.push([f, flagCounts[f]]));
  }

  sumSheet.getRange(1, 1, summaryRows.length, 2).setValues(summaryRows);
  sumSheet.getRange('A1:B1').setFontWeight('bold');
  sumSheet.getRange('A7:B7').setFontWeight('bold');
}
